// MONTAR EXPORT — junta Leads + Comerciais + Historico num formato pronto a
// converter para CSV do lado do Terminal (um comercial por id, um lead por linha).
const pega = nome => { try { return $(nome).all().map(i => i.json); } catch (e) { return []; } };
const F = r => r.fields || r;
const id = r => r.id || F(r).id || null;
const um = v => Array.isArray(v) ? (v[0] || null) : (v || null);
const txt = (f, ...ks) => { for (const k of ks) if (f[k] !== undefined && f[k] !== null && f[k] !== '') return f[k]; return null; };

const comerciaisPorId = {};
for (const r of pega('Comerciais')) {
  const f = F(r);
  comerciaisPorId[id(r)] = txt(f, 'Nome', 'nome') || '';
}

const leadsPorId = {};
const leads = pega('Leads').map(r => {
  const f = F(r);
  const lid = id(r);
  const comercialId = um(f.Comercial || f.Comerciais || f.comercial);
  const row = {
    id: lid,
    nome: txt(f, 'Nome', 'nome') || '',
    telefone: txt(f, 'Telefone', 'telefone') || '',
    email: txt(f, 'Email', 'email') || '',
    comercial: comerciaisPorId[comercialId] || '',
    estagio: txt(f, 'estagio', 'Estagio', 'Estágio') || '',
    status: txt(f, 'Status', 'status') || '',
    tipo: txt(f, 'tipo', 'Tipo') || '',
    origem_lead: txt(f, 'origem_lead', 'Origem') || '',
    valor: f.Valor ?? f.valor ?? '',
    banco_origem: txt(f, 'banco_origem') || '',
    motivo_saida: txt(f, 'motivo_saida') || '',
    ultima_nota: txt(f, 'ultima_nota', 'Ultima_nota') || '',
  };
  leadsPorId[lid] = row;
  return row;
}).filter(l => l.nome);

const historico = pega('Historico').map(r => {
  const f = F(r);
  const leadId = um(f.Lead || f.Leads);
  const lead = leadsPorId[leadId] || {};
  return {
    id: id(r),
    lead_nome: lead.nome || '',
    lead_telefone: lead.telefone || '',
    data: txt(f, 'Data', 'data') || '',
    tipo_registo: txt(f, 'tipo_registo') || '',
    desfecho: txt(f, 'desfecho') || '',
    nota: txt(f, 'nota', 'Nota') || '',
  };
}).filter(h => h.nota || h.lead_nome);

return [{ json: { ok: true, gerado_em: new Date().toISOString(), leads, historico } }];

// IMPORTAR — cria/actualiza leads e regista histórico a partir de um CSV externo.
// Regras de segurança (CLAUDE.md: nunca apagar, decisões destrutivas ficam do lado do César):
//  - Leads existentes (por telefone): só preenche campos que estejam VAZIOS. Nunca sobrescreve
//    um valor já existente.
//  - Histórico: só cria, nunca actualiza nem apaga.
//  - dry_run:true (por omissão) calcula o plano mas não escreve nada no Airtable.

const BASE = 'appIdD2RG5S0lWvfV';
const TBL_LEADS = 'tblO1ODpXI5GInKGn';
const TBL_HIST = 'tblYNuUEylWey2Wsf';

const body = $input.first().json.body || {};
const comercial_id = (body.comercial_id || '').trim();
const linhasLeads = Array.isArray(body.leads) ? body.leads : [];
const linhasHist = Array.isArray(body.historico) ? body.historico : [];
const dryRun = body.dry_run !== false; // por omissão, dry-run

if (!comercial_id) throw new Error('comercial_id em falta.');
if (!linhasLeads.length && !linhasHist.length) throw new Error('Nada para importar (leads e historico vazios).');

const normTel = (t) => { const d = String(t || '').replace(/\D/g, ''); return d.slice(-9); };
const limpo = (v) => (v === undefined || v === null) ? '' : String(v).trim();

async function airtableList(table) {
  const registos = [];
  let offset;
  do {
    const resp = await this.helpers.httpRequestWithAuthentication.call(this, 'airtableTokenApi', {
      method: 'GET',
      url: `https://api.airtable.com/v0/${BASE}/${table}`,
      qs: offset ? { pageSize: 100, offset } : { pageSize: 100 },
      json: true,
    });
    registos.push(...(resp.records || []));
    offset = resp.offset;
  } while (offset);
  return registos;
}

async function airtableBatch(table, method, records) {
  const out = [];
  for (let i = 0; i < records.length; i += 10) {
    const lote = records.slice(i, i + 10);
    const resp = await this.helpers.httpRequestWithAuthentication.call(this, 'airtableTokenApi', {
      method,
      url: `https://api.airtable.com/v0/${BASE}/${table}`,
      body: { records: lote, typecast: true },
      json: true,
    });
    out.push(...(resp.records || []));
  }
  return out;
}

// ---- 1. carregar leads existentes, indexar por telefone ----
const leadsExistentes = await airtableList.call(this, TBL_LEADS);
const porTelefone = new Map();
for (const r of leadsExistentes) {
  const f = r.fields || {};
  const tel = normTel(f.Telefone || f.telefone);
  if (tel) porTelefone.set(tel, r);
}

// ---- 2. planear leads: criar vs actualizar (só campos vazios) ----
const MAPA_LEAD = {
  nome: 'Nome', email: 'Email', estagio: 'estagio', status: 'Status', tipo: 'tipo',
  origem_lead: 'origem_lead', valor: 'Valor', banco_origem: 'banco_origem', ultima_nota: 'ultima_nota',
};

const aCriar = [];
const aAtualizar = [];
const avisos = [];

for (const linha of linhasLeads) {
  const nome = limpo(linha.nome);
  const tel = normTel(linha.telefone);
  if (!nome && !tel) { avisos.push('Linha de lead sem nome nem telefone — ignorada.'); continue; }

  const existente = tel ? porTelefone.get(tel) : null;
  if (existente) {
    const fExist = existente.fields || {};
    const patch = {};
    for (const [origem, destino] of Object.entries(MAPA_LEAD)) {
      const valorNovo = limpo(linha[origem]);
      const valorActual = fExist[destino];
      const vazio = valorActual === undefined || valorActual === null || valorActual === '';
      if (vazio && valorNovo) patch[destino] = origem === 'valor' ? Number(valorNovo) || valorNovo : valorNovo;
    }
    if (Object.keys(patch).length) aAtualizar.push({ id: existente.id, fields: patch });
  } else {
    if (!nome) { avisos.push(`Lead com telefone ${tel || '(sem telefone)'} sem nome — ignorada.`); continue; }
    const fields = { Nome: nome, Comercial: [comercial_id] };
    if (tel) fields.Telefone = linha.telefone;
    for (const [origem, destino] of Object.entries(MAPA_LEAD)) {
      if (origem === 'nome') continue;
      const v = limpo(linha[origem]);
      if (v) fields[destino] = origem === 'valor' ? Number(v) || v : v;
    }
    aCriar.push({ fields, _tel: tel });
  }
}

// ---- 3. executar (ou não, em dry-run) ----
let criados = [];
let atualizados = [];
if (!dryRun) {
  if (aAtualizar.length) atualizados = await airtableBatch.call(this, TBL_LEADS, 'PATCH', aAtualizar);
  if (aCriar.length) {
    criados = await airtableBatch.call(this, TBL_LEADS, 'POST', aCriar.map(c => ({ fields: c.fields })));
    // liga os recém-criados ao mapa de telefones, para o histórico já os poder encontrar
    criados.forEach((r, i) => { const tel = aCriar[i]._tel; if (tel) porTelefone.set(tel, r); });
  }
}

// ---- 4. planear histórico: só cria, nunca actualiza ----
const histACriar = [];
for (const linha of linhasHist) {
  const tel = normTel(linha.lead_telefone);
  const nota = limpo(linha.nota);
  if (!nota) continue;
  const lead = tel ? porTelefone.get(tel) : null;
  if (!lead) { avisos.push(`Histórico "${nota.slice(0, 40)}…" sem lead correspondente (telefone ${tel || '?'}) — ignorado.`); continue; }
  histACriar.push({
    fields: {
      Registo: 'Importado',
      tipo_registo: 'importado',
      nota,
      Lead: [lead.id],
      Data: limpo(linha.data) || new Date().toISOString().slice(0, 10),
      ...(limpo(linha.desfecho) ? { desfecho: limpo(linha.desfecho) } : {}),
    },
  });
}

let histCriado = [];
if (!dryRun && histACriar.length) {
  histCriado = await airtableBatch.call(this, TBL_HIST, 'POST', histACriar);
}

return [{
  json: {
    ok: true,
    dry_run: dryRun,
    leads_criadas: dryRun ? aCriar.length : criados.length,
    leads_atualizadas: dryRun ? aAtualizar.length : atualizados.length,
    historico_criado: dryRun ? histACriar.length : histCriado.length,
    avisos,
  },
}];
